import { expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { createGame } from '../src/game/game.ts';
import { decodeSnapshot, encodeSnapshot } from '../src/game/snapshot.ts';

export const cards = (page: Page) => page.getByRole('group', { name: 'Memory board', exact: true }).getByRole('button');

export async function tools(page: Page): Promise<void> {
  if (!await page.locator('details').getAttribute('open').then((value) => value !== null)) {
    await page.getByText('Reproduce a game', { exact: true }).click();
  }
}

export async function loadBoard(page: Page, code = 'np1-4-1'): Promise<void> {
  await tools(page);
  await page.getByLabel('Board code', { exact: true }).fill(code);
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
  await expect(page.locator('.load-status')).toHaveText('Loaded board.');
}

export async function loadSnapshot(page: Page, text: string): Promise<void> {
  await tools(page);
  await page.getByLabel('Snapshot JSON', { exact: true }).fill(text);
  await page.getByRole('button', { name: 'Load snapshot', exact: true }).click();
}

export async function exported(page: Page) {
  await tools(page);
  await page.getByRole('button', { name: 'Export snapshot', exact: true }).click();
  const state = decodeSnapshot(await page.getByLabel('Snapshot JSON', { exact: true }).inputValue());
  if (!state) throw new Error('Browser exported an invalid snapshot.');
  return state;
}

export function snapshot(overrides: Record<string, unknown> = {}): string {
  return JSON.stringify({ version: 1, boardCode: 'np1-4-1', matched: [], selection: { kind: 'closed' },
    moves: 0, elapsedMs: 0, started: false, ...overrides });
}

export function almostWon(moves = 7, elapsedMs = 1500): string {
  const game = createGame('np1-4-1');
  return encodeSnapshot({ ...game, moves, elapsedMs, started: true,
    matched: game.deck.map((_, index) => index).filter((index) => index !== 0 && index !== 11) });
}

export async function frozen(page: Page): Promise<void> {
  await page.clock.install({ time: new Date('2026-11-04T00:00:00Z') });
  await page.goto('/');
  await page.clock.pauseAt(new Date('2026-11-04T00:00:01Z'));
}

export async function keyboardTo(page: Page, from: number, to: number, size = 4): Promise<void> {
  const row = Math.floor(from / size);
  const column = from % size;
  const targetRow = Math.floor(to / size);
  const targetColumn = to % size;
  for (let step = 0; step < Math.abs(targetRow - row); step += 1) {
    await page.keyboard.press(targetRow > row ? 'ArrowDown' : 'ArrowUp');
  }
  for (let step = 0; step < Math.abs(targetColumn - column); step += 1) {
    await page.keyboard.press(targetColumn > column ? 'ArrowRight' : 'ArrowLeft');
  }
  await expect(cards(page).nth(to)).toBeFocused();
}
import { expect, test } from '@playwright/test';
import { supportedSizes } from '../src/game/boardCode.ts';
import { createGame } from '../src/game/game.ts';
import { cards, exported, frozen, loadBoard, loadSnapshot, snapshot } from './actions.ts';

for (const size of supportedSizes) {
  test(`finishes every pair on a ${size}x${size} board`, async ({ page }) => {
    await page.goto('/');
    await loadBoard(page, `np1-${size}-1`);
    const game = createGame(`np1-${size}-1`);
    for (let face = 0; face < size * size / 2; face += 1) {
      await cards(page).nth(game.deck.indexOf(face)).click();
      await cards(page).nth(game.deck.lastIndexOf(face)).click();
    }
    await expect(page.getByRole('region', { name: 'Game complete' })).toBeVisible();
    await expect(page.getByText(`Pairs: ${size * size / 2}/${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(page.getByText(`Moves: ${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(page.locator('.card--matched')).toHaveCount(size * size);
    await expect(page.locator('[aria-live]')).toContainText(`All pairs found in ${size * size / 2} moves`);
  });
}

test('counts one move per second reveal and resolves exactly 800 active milliseconds', async ({ page }) => {
  await frozen(page);
  await loadBoard(page);
  await page.clock.runFor(10000);
  expect((await exported(page)).elapsedMs).toBe(0);
  await cards(page).nth(0).click();
  await cards(page).nth(0).click();
  await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
  await page.clock.runFor(1250);
  await cards(page).nth(11).click();
  await expect(page.getByText('Pairs: 1/8', { exact: true })).toBeVisible();
  await cards(page).nth(0).click({ force: true });
  await expect(page.getByText('Moves: 1', { exact: true })).toBeVisible();
  await cards(page).nth(1).click();
  await cards(page).nth(2).click();
  await cards(page).nth(3).click({ force: true });
  await page.clock.runFor(799);
  await expect(page.locator('.card-face')).toHaveCount(4);
  await page.clock.runFor(1);
  await expect(page.locator('.card-face')).toHaveCount(2);
  const state = await exported(page);
  expect(state.moves).toBe(2);
  expect(state.elapsedMs).toBe(2050);
});

test('caps counters while allowing mismatch expiry and completion', async ({ page }) => {
  await frozen(page);
  await loadSnapshot(page, snapshot({ moves: 999999, elapsedMs: 359999999, started: true }));
  await page.getByRole('button', { name: 'Resume', exact: true }).click();
  await cards(page).nth(0).click();
  await cards(page).nth(1).click();
  await page.clock.runFor(800);
  await expect(page.locator('.card-face')).toHaveCount(0);
  const game = createGame('np1-4-1');
  for (let face = 0; face < 8; face += 1) {
    await cards(page).nth(game.deck.indexOf(face)).click();
    await cards(page).nth(game.deck.lastIndexOf(face)).click();
  }
  await expect(page.getByText('Moves: 999999', { exact: true })).toBeVisible();
  await expect(page.getByText('Time: 5999:59', { exact: true })).toBeVisible();
  const final = await exported(page);
  await page.clock.runFor(10000);
  expect(await exported(page)).toEqual(final);
});
