    let disposed = false;
    let pending: number | undefined;
    const valid = () => !disposed && current.current.revision === revision;
    function clear(): void {
      if (pending !== undefined) window.clearTimeout(pending);
      pending = undefined;
    }
    function schedule(): void {
      if (!valid()) return;
      const { game, paused } = current.current;
      if (document.hidden || paused || !game.started || isWon(game)) return;
      const delay = game.selection.kind === selectionKinds.mismatch
        ? Math.max(1, Math.min(CLOCK_REFRESH_MS, game.selection.remainingMs)) : CLOCK_REFRESH_MS;
      pending = window.setTimeout(tick, delay);
    }
    function tick(): void {
      if (!valid()) return;
      flush();
      schedule();
    }
    function visibilityChanged(): void {
      if (!valid()) return;
      flush();
      clear();
      schedule();
    }
    document.addEventListener('visibilitychange', visibilityChanged);
    schedule();
    return () => {
      disposed = true;
      clear();
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [view.revision, view.paused, view.game.started, won]);

  return {
    ...view, best: view.preferences.bests[view.game.board.size] ?? null,
    activate(index: number): void {
      const session = flush();
      if (!document.hidden) publish(activateSession(session, index));
    },
    newGame(): void {
      const { game } = current.current;
      replace(replaceSession(current.current, freshDeal(game.board.size, game.board.seed)));
    },
    restart(): void {
      replace(replaceSession(current.current, createGame(current.current.game.board.code)));
    },
    chooseSize(size: GridSize): void {
      if (size === current.current.game.board.size) return;
      replace(replaceSession(current.current, freshDeal(size, current.current.game.board.seed)));
    },
    loadBoard(draft: string): boolean {
      const previous = current.current;
      const next = loadBoard(previous, draft);
      if (next.revision !== previous.revision) replace(next); else publish(next);
      return next.revision !== previous.revision;
    },
    loadSnapshot(draft: string): boolean {
      const previous = current.current;
      const next = loadSnapshot(previous, draft);
      if (next.revision !== previous.revision) replace(next); else publish(next);
      return next.revision !== previous.revision;
    },
    resume(): void {
      if (!current.current.paused) return;
      publish({ ...current.current, paused: false, loadStatus: '' });
      resetClock();
    },
    exportSnapshot(): string { return encodeSnapshot(flush().game); },
  };
}

export type GameSession = ReturnType<typeof useGameSession>;
import { useImperativeHandle, useRef, useState } from 'react';
import type { CSSProperties, KeyboardEvent, Ref } from 'react';
import { isCardRevealed, selectionKinds } from '../state.ts';
import type { GameState } from '../state.ts';
import { Card } from './Card.tsx';
import { arrowDestination } from './navigation.ts';
import './Board.css';

export interface BoardHandle { focusRemembered(): void }
export interface BoardProps {
  readonly game: GameState;
  readonly blocked: boolean;
  readonly revision: number;
  readonly onActivate: (index: number) => void;
  readonly ref?: Ref<BoardHandle>;
}

export function Board({ game, blocked, revision, onActivate, ref }: BoardProps) {
  const [memory, setMemory] = useState({ revision, index: 0 });
  const cards = useRef(new Map<number, HTMLButtonElement>());
  const remembered = memory.revision === revision ? memory.index : 0;
  useImperativeHandle(ref, () => ({
    focusRemembered(): void { cards.current.get(remembered)?.focus(); },
  }), [remembered, revision]);

  function focus(index: number, button: HTMLButtonElement): void {
    setMemory({ revision, index });
    button.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  }

  function navigate(event: KeyboardEvent<HTMLButtonElement>, index: number): void {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const next = arrowDestination(index, game.board.size, event.key);
    if (next === null) return;
    event.preventDefault();
    cards.current.get(next)?.focus();
  }

  const size = game.board.size;
  const style: CSSProperties = {
    gridTemplateColumns: `repeat(${size}, clamp(44px, calc((100cqw - ${(size - 1) * 6}px) / ${size}), 88px))`,
  };
  const activationBlocked = blocked || game.selection.kind === selectionKinds.mismatch;
  return (
    <div className="board-scroll" role="group" aria-label="Memory board">
      <div className="board-grid" style={style}>
        {game.deck.map((faceId, index) => (
          <Card key={index} index={index} size={size} faceId={faceId}
            revealed={isCardRevealed(game, index)} matched={game.matched.includes(index)}
            blocked={activationBlocked} tabIndex={remembered === index ? 0 : -1}
            buttonRef={(button) => {
              if (button) cards.current.set(index, button); else cards.current.delete(index);
            }}
            onActivate={onActivate} onFocus={focus} onKeyDown={navigate} />
        ))}
      </div>
    </div>
  );
}
