}

export function savePreferences(preferences: Preferences, storage: PreferenceStorage | null = browserStorage()): void {
  try {
    storage?.setItem(PREFERENCES_KEY, JSON.stringify({ version: PREFERENCES_VERSION, ...preferences }));
